def add_item(self, sku, unit_price, quantity=1):
        """Add a line item to the cart.

        If the SKU already exists we accumulate the quantity.  The
        ``unit_price`` for an existing SKU must match the previously
        recorded price – if it differs we raise a ``ValueError``.
        """
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        if sku in self.items:
            existing_price, existing_qty = self.items[sku]
            if existing_price != unit_price:
                raise ValueError("Unit price mismatch for SKU %s" % sku)
            self.items[sku] = (unit_price, existing_qty + quantity)
        else:
            self.items[sku] = (unit_price, quantity)

